// features/lifecycle.feature: A page past the last vendor is empty but still reports the total
import { expect, expectStatus, test } from "../../fixtures";

interface VendorPage {
  items: unknown[];
  total: number;
  limit: number;
  offset: number;
}

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
  // Arrange: at least one vendor exists for the member's tenant
  await factory.vendor();
  const member = await apiAs("member");

  // Act: list past the end, bracketed by first-page reads so concurrent creates from parallel tests can't skew the comparison
  let firstTotal = -1;
  let past: VendorPage = { items: [], total: -1, limit: 0, offset: 0 };
  let offset = 0;
  await expect
    .poll(
      async () => {
        const before = await expectStatus<VendorPage>(await member.get("/api/vendors"), 200);
        offset = before.total + 1000;
        past = await expectStatus<VendorPage>(await member.get("/api/vendors", { params: { offset } }), 200);
        const after = await expectStatus<VendorPage>(await member.get("/api/vendors"), 200);
        firstTotal = after.total;
        return before.total === after.total && after.total === past.total;
      },
      { message: "vendor total is stable across the first-page and past-the-end reads", timeout: 30_000 },
    )
    .toBe(true);

  // Assert
  expect(firstTotal).toBeGreaterThan(0);
  expect(offset).toBeGreaterThan(firstTotal);
  expect(past.items).toEqual([]);
  expect(past.total).toBe(firstTotal);
  expect(past.offset).toBe(offset);
});
